package main

import "context"

// A worker with a guaranteed exit via ctx.Done() — never leaks.
func worker(ctx context.Context, ch <-chan int) {
	for {
		select {
		case <-ctx.Done(): // cancellation path: the exit
			return
		case v, ok := <-ch:
			if !ok {
				return // closed channel: also an exit
			}
			_ = v
		}
	}
}

package main

import (
	"context"
	"net/http"
	"time"
)

func fetch(ctx context.Context, url string) (*http.Response, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel() // release the timer/resources no matter what

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	return http.DefaultClient.Do(req) // aborts at the deadline, no hang
}

