package main

import "sync"

// Guarded counter: safe for concurrent increments.
type Counter struct {
	mu sync.Mutex
	n  int
}

func (c *Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock() // guaranteed release even on panic
	c.n++               // without the lock this is a data race
}

