package main

import (
	"io"
	"net/http"
)

func read(url string) ([]byte, error) {
	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()          // release the connection back to the pool
	body, err := io.ReadAll(resp.Body)
	io.Copy(io.Discard, resp.Body)   // drain so the conn can be reused
	return body, err
}

package main

import "sync"

func process(items []string, work func(string)) {
	sem := make(chan struct{}, 100) // cap concurrency at 100
	var wg sync.WaitGroup
	for _, it := range items {
		wg.Add(1)
		sem <- struct{}{} // acquire a slot (blocks once 100 in flight)
		go func(it string) {
			defer wg.Done()
			defer func() { <-sem }() // release the slot
			work(it)
		}(it)
	}
	wg.Wait()
}

