package solution

import (
	"context"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestFetchAll(t *testing.T) {
	t.Run("order and cap", func(t *testing.T) {
		var inFlight, maxSeen int32
		var mu sync.Mutex
		fetch := func(_ context.Context, id int) int {
			n := atomic.AddInt32(&inFlight, 1)
			mu.Lock()
			if n > maxSeen {
				maxSeen = n
			}
			mu.Unlock()
			time.Sleep(5 * time.Millisecond)
			atomic.AddInt32(&inFlight, -1)
			return id * 10
		}
		ids := []int{1, 2, 3, 4, 5}
		got := FetchAll(context.Background(), ids, 2, fetch)
		want := []int{10, 20, 30, 40, 50}
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("got %v want %v", got, want)
			}
		}
		if maxSeen > 2 {
			t.Fatalf("concurrency %d exceeded cap of 2", maxSeen)
		}
	})
}

