func process(items []string) {
	var wg sync.WaitGroup
	for _, it := range items {
		wg.Add(1)              // increment BEFORE launching
		go func(it string) {   // pass it as an argument -> per-goroutine copy
			defer wg.Done()
			fmt.Println(it)
		}(it)
	}
	wg.Wait()                  // now correctly waits for every goroutine
}

func DoWithTimeout(ctx context.Context, work func() (int, error)) (int, error) {
	type result struct {
		val int
		err error
	}
	done := make(chan result, 1) // buffered(1): send never blocks -> no leak
	go func() {
		v, err := work()
		done <- result{v, err} // always succeeds, goroutine then exits
	}()
	select {
	case <-ctx.Done():
		return 0, ctx.Err() // timed out/cancelled; goroutine still finishes into the buffer
	case r := <-done:
		return r.val, r.err
	}
}

// BEFORE (bug): the returned slice pins the entire big backing array.
func firstBytesLeak(big []byte, n int) []byte {
	if n > len(big) {
		n = len(big)
	}
	return big[:n] // header still references all of big -> big can't be GC'd
}

// AFTER (fix): copy the window into a fresh, small backing array.
func firstBytes(big []byte, n int) []byte {
	if n > len(big) {
		n = len(big)
	}
	out := make([]byte, n) // independent backing array of exactly n bytes
	copy(out, big[:n])     // copy the needed window out
	return out             // big is now unreferenced and collectible
}

// (Go 1.21+: slices.Clone(big[:n]) is an idiomatic one-liner equivalent.)
